<template><section><el-alert title="这里保留评审轮次启用前的正式意见及修订，不代表当前授权范围。" type="info" :closable="false" /><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-button :loading="loading" @click="load(page)">刷新旧版意见</el-button><el-table :data="rows" v-loading="loading" border :empty-text="loading?'正在加载旧版意见…':error?'加载失败，请重试':'暂无旧版正式意见'"><el-table-column type="expand"><template #default="{row}"><div class="legacy-text">{{ row.review_text }}</div></template></el-table-column><el-table-column prop="expert_name" label="专家" width="120" /><el-table-column prop="review_year" label="年度" width="90" /><el-table-column prop="task_code" label="任务编号" width="160" /><el-table-column prop="task_name" label="任务名称" min-width="270" /><el-table-column label="结论" width="100"><template #default="{row}"><el-tag :type="row.review_result==='pass'?'success':row.review_result==='reject'?'danger':'info'">{{ row.review_result==='pass'?'通过':row.review_result==='reject'?'不通过':'未记录' }}</el-tag></template></el-table-column><el-table-column prop="revision_no" label="版本" width="80" /><el-table-column label="提交时间" min-width="170"><template #default="{row}">{{ String(row.create_time || '').replace('T',' ') }}</template></el-table-column></el-table><p>点击每行左侧箭头查看完整评语。</p><el-pagination v-if="initialized" :total="total" :current-page="page" :page-size="50" layout="total,prev,pager,next" @current-change="load" /></section></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {get} from '@/utils/request'
const rows=ref([]),page=ref(1),total=ref(0),loading=ref(true),initialized=ref(false),error=ref('');let controller,disposed=false
async function load(n){controller?.abort();const c=new AbortController();controller=c;loading.value=true;error.value='';try{const r=await get('/review-history',{page:n},{signal:c.signal});if(!disposed&&controller===c){rows.value=r.items;total.value=r.total;page.value=n;initialized.value=true}}catch(e){if(!disposed&&controller===c&&e.name!=='AbortError')error.value=e.message}finally{if(controller===c)loading.value=false}}
onMounted(()=>load(1));onBeforeUnmount(()=>{disposed=true;controller?.abort()})
</script>
<style scoped>.legacy-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;padding:20px 32px}section>.el-button{margin:14px 0}section>p{color:#738196;font-size:13px}.el-pagination{justify-content:flex-end;margin:16px 0}</style>
